"""Plain-language, evidence-first display of the executed retrieval experiment."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parent
latest=json.loads((OUT/'latest.json').read_text());report=json.loads(Path(latest['results']).read_text(encoding='utf-8'))
m=json.loads((OUT.parent/'graph.json').read_text(encoding='utf-8'))
labels={'prototype_kg':'Our KG — first attempt','improved_kg':'Our KG — improved connections','default_hybrid':'Current meaning-based search','prepared_hybrid':'Current combined search — prepared links','prepared_graph':'Current graph search — prepared links','default_graph':'Current graph search — default settings'}
data={'report':report,'model':m,'labels':labels}
HTML=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Can the graph find what we need?</title><style>
:root{color-scheme:dark;--bg:#101924;--panel:#192737;--line:#3b5268;--text:#eef5fb;--muted:#b5c7d7;--green:#87dcc0;--gold:#f0ce85}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui}header{padding:25px 30px;border-bottom:1px solid var(--line)}h1{font-size:30px;margin:6px 0 10px}h2{font-size:20px;margin:0 0 12px}h3{font-size:16px;margin:8px 0}p{line-height:1.6;color:var(--muted)}.tag{font-size:11px;color:var(--green);text-transform:uppercase;letter-spacing:1.4px}main{max-width:1480px;margin:auto;padding:24px;display:grid;gap:20px}.panel{min-width:0;padding:20px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.intro{display:grid;grid-template-columns:1.2fr 1fr;gap:20px}.headline{padding:14px;border:1px solid #617b69;border-radius:8px;background:#19392f;color:#d6f0e5;line-height:1.6}.caution{padding:14px;border:1px solid #816d48;border-radius:8px;color:#f0d9b1;background:#312a1e;line-height:1.6;margin-top:12px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:11px 8px;border-bottom:1px solid var(--line);text-align:left}.small{font-size:12px;color:var(--muted)}a{color:#a3d2fc}select,button{min-width:0;font:inherit;border:1px solid #627e95;border-radius:6px;color:var(--text);background:#243b51;padding:10px;max-width:100%}button{cursor:pointer}select:focus-visible,button:focus-visible{outline:3px solid #b1d8f8}.toolbar{display:grid;gap:12px;grid-template-columns:minmax(220px,2fr) minmax(210px,1fr)}.comparison{display:grid;grid-template-columns:1fr 1.65fr;gap:20px}.reference{border:1px solid #65847e;border-radius:8px;padding:15px;background:#203932}.badge{display:inline-block;padding:5px 8px;border:1px solid #677c90;border-radius:6px;font-size:12px;margin:4px}.ok{color:var(--green);border-color:#78b4a0}.missing{color:var(--gold);border-color:#af925a}.card{margin:12px 0;padding:13px;border:1px solid #465f77;border-radius:8px}.card p{font-size:13px}.original{border-left:3px solid #607d97;padding-left:12px;font-size:12px;max-height:180px;overflow:auto}.ideas{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.idea{padding:13px;border:1px solid #4f687d;border-radius:9px}.idea p{font-size:13px}.question{font-size:21px;line-height:1.5;margin:14px 0}.pill{display:inline-block;font-size:12px;padding:7px;border:1px solid #53768c;border-radius:7px}summary{cursor:pointer;color:#add7f9;font-size:13px}details{margin-top:12px}.legend{display:flex;gap:10px;flex-wrap:wrap}@media(max-width:800px){header{padding:18px}main{padding:12px}.intro,.comparison,.ideas,.toolbar{grid-template-columns:1fr}h1{font-size:25px}table{min-width:580px}}
</style></head><body><header><div class="tag">Executed demo · random test data · existing application unchanged</div><h1>Can the graph find the information we need?</h1><p>We tried 30 questions, made one small graph-search improvement, then tried 10 additional questions without further tuning.</p><a href="../index.html">Back to the graph</a></header><main>
<section class="intro"><div class="panel"><h2>The result</h2><div class="headline">The graph is useful, but it needs help understanding different wording and recognizing when an answer is missing. Better field lookup and related evidence paths repaired two misses.</div><p>“Complete evidence” means the search returned all the notes needed for the test's reference answer, within a limit of ten evidence items. It does not mean the system automatically wrote a correct answer.</p><div class="caution">The answers below were written as test references. The search returned evidence, not those answers. This is a small demonstration on carefully prepared data, not a general accuracy score.</div></div><div class="panel"><h2>What changed in the demo?</h2><p><b>First:</b> find notes by their wording and follow the existing policy links.</p><p><b>Improved:</b> also search individual fields and follow specific project, internship and organization connections. Avoid broad links that would pull in almost everything about the person.</p><p><b>Still missing:</b> a reliable check that the returned information actually answers the requested question.</p></div></section>
<section class="panel"><h2>Same evidence budget, different search methods</h2><p class="small">28 original questions had reference evidence. Two asked for information that was not supplied. Both systems received the same 91 prepared notes plus the organization clarification. The current search used its real, locally cached meaning-search model.</p><div class="scroll"><table id="scores"><thead><tr><th>Search method</th><th>Complete within first 5</th><th>Complete with up to 10</th><th>What this tells us</th></tr></thead><tbody></tbody></table></div><p class="small">Prepared links were supplied by hand for the comparison. The current default saves text without automatically creating those links. Its default combined search still finds text through its meaning-based search.</p></section>
<section class="panel"><h2>The additional questions</h2><div class="scroll"><table id="holdout"><thead><tr><th>Search method</th><th>Complete evidence</th></tr></thead><tbody></tbody></table></div><p>Nine additional questions had reference evidence. One asked for an unspecified FastAPI version. All three methods returned related notes for that version request; none demonstrated a dependable “this information is missing” check.</p><p class="small">The improved KG also missed a differently worded qualification question. These ten questions were not used to make another improvement.</p></section>
<section class="panel"><h2>Try a question and inspect what was returned</h2><div class="toolbar"><select id="question" aria-label="Choose test question"></select><select id="system" aria-label="Choose search method"></select></div><div class="question" id="questionText"></div><div class="comparison"><div><div class="reference"><h3>Reference answer for this test</h3><p id="answer"></p><div class="small">Written for evaluation; not generated by the search system.</div></div><h3>Was the evidence complete?</h3><div id="outcome"></div><h3>Which information was needed?</h3><div id="needed"></div><div class="caution" id="warning"></div></div><div><h3>What the search actually returned</h3><div class="legend"><span class="badge ok">Needed evidence</span><span class="badge">Other returned information</span></div><div id="returned"></div><div id="relationships"></div></div></div></section>
<section class="panel"><h2>What the replacement checks showed</h2><p>In separate synthetic tests, the current system labelled replaced notes but could still return them for a current question. Explicitly giving the old note an expiry date made its current and history searches work correctly.</p><p>The new graph keeps an accepted replacement eligible for current use and keeps the earlier claim in its audit history. An unresolved contradiction keeps both claims and explicitly calls for resolution.</p><p>A score of 1 in the current system does not provide the special “never age unless directly replaced” protection. Its existing age weighting and the new graph's acceptance score serve different purposes.</p></section>
<section class="panel"><h2>How to improve the application</h2><div class="ideas"><div class="idea"><h3>1 · Find by meaning, check in the graph</h3><p>Let meaning search understand varied wording. Let the graph bring back connected evidence, conditions, replacements and unresolved disagreements.</p></div><div class="idea"><h3>2 · Ask what is actually known</h3><p>“Uses FastAPI” cannot answer “which version?” Mark a missing answer even when related memories were found.</p></div><div class="idea"><h3>3 · Keep complete evidence</h3><p>A tone correction needs its baseline. An internship question may need the employment report. Retrieve these companions deliberately.</p></div><div class="idea"><h3>4 · Save facts with their limits</h3><p>Keep the source, individual fields, conditions, and event-date uncertainty. Treat a goal as a goal and a partial course as partial progress.</p></div><div class="idea"><h3>5 · Manage changes explicitly</h3><p>An accepted correction changes what can be used now, while retaining the old claim. A disputed claim needs a visible warning even at score 1.</p></div><div class="idea"><h3>6 · Test before switching</h3><p>Build the new memory view alongside the existing one. Compare varied questions, irrelevant memories, unknown answers and old-versus-current questions before using it by default.</p></div></div></section>
<section class="panel"><h2>Evidence and limits</h2><p>This demonstration read the stored prototype graph and ran the existing application search in separate test databases. The current application and its saved memories were not changed. The data preparation was manual, so this does not test whether automatic memory creation is reliable.</p><p>No final-answer generation was evaluated. Finding a relevant note does not prove an assistant will interpret it correctly. These results do not establish performance on a large graph.</p><a href="REPORT.md">Plain-language report</a> · <a href="results.json">Full recorded retrieval results</a> · <a href="questions.json">Original question set</a> · <a href="holdout.json">Additional question set</a></section>
</main><script>const data=__DATA__,report=data.report,m=data.model,labels=data.labels,all=[...report.results,...report.holdout],records=[...m.old.records,...m.new_records],recordMap=Object.fromEntries(records.map(r=>[r.id,r])),keys=Object.fromEntries(records.map(r=>[r.key,r.id])),sources=Object.fromEntries([...m.old.sources,...m.new_sources,m.clarification_source].map(s=>[s.id,s]));keys.C_ORG='C_ORG';let chosen=0,system='improved_kg';
function add(parent,tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;parent.append(e);return e}function title(id){return id==='C_ORG'?'User-confirmed Inditech identity':recordMap[id]?.title||id}const notes={prototype_kg:'Useful structure; misses some related facts.',improved_kg:'Two original misses repaired; wording and missing-answer problems remain.',default_hybrid:'Good at different wording; relationship context is uneven.',prepared_hybrid:'More links alone did not improve the ten-item result here.',prepared_graph:'Name-led lookup struggles to find the right notes.',default_graph:'No useful entity links were created under default ingestion.'};
for(const name of['prototype_kg','improved_kg','default_hybrid','prepared_hybrid','prepared_graph','default_graph']){const s=report.summary[name],tr=document.createElement('tr');document.querySelector('#scores tbody').append(tr);for(const x of[labels[name],`${s.complete_top5} / ${s.questions_with_reference_evidence}`,`${s.complete_evidence_budget10} / ${s.questions_with_reference_evidence}`,notes[name]])add(tr,'td',x)}for(const name of['prototype_kg','improved_kg','default_hybrid']){const s=report.holdout_summary[name],tr=document.createElement('tr');document.querySelector('#holdout tbody').append(tr);add(tr,'td',labels[name]);add(tr,'td',`${s.complete_evidence_budget10} / ${s.questions_with_reference_evidence}`)}
for(let i=0;i<all.length;i++){const q=all[i].question,o=document.createElement('option');o.value=i;o.textContent=q.id+' · '+q.question;document.querySelector('#question').append(o)}
function options(){const select=document.querySelector('#system');select.replaceChildren();for(const name of Object.keys(all[chosen].runs)){const o=document.createElement('option');o.value=name;o.textContent=labels[name];select.append(o)}if(!all[chosen].runs[system])system='improved_kg';select.value=system}
function render(){const q=all[chosen].question,r=all[chosen].runs[system],needed=new Set(q.gold.flatMap(g=>g.map(k=>keys[k])));document.querySelector('#questionText').textContent=q.question;document.querySelector('#answer').textContent=q.answer;const outcome=document.querySelector('#outcome');outcome.replaceChildren();add(outcome,'div',q.gold.length?(r.expanded.complete?'All required reference evidence found':'Some required reference evidence missing'):(r.evidence_ids.length?'Related information returned; it does not supply the requested fact':'No information returned'),'badge '+(r.expanded.complete?'ok':'missing'));const ns=document.querySelector('#needed');ns.replaceChildren();if(!q.gold.length)add(ns,'p','The requested fact is absent from the supplied data.');else for(const g of q.gold)add(ns,'p',g.map(k=>title(keys[k])).join(' OR '));document.querySelector('#warning').textContent='A search result is evidence to inspect. A missing fact, goal, or unresolved relationship still requires careful interpretation.';const box=document.querySelector('#returned');box.replaceChildren();if(!r.evidence_ids.length)add(box,'p','No search results.');for(let i=0;i<r.evidence_ids.length;i++){const id=r.evidence_ids[i],card=add(box,'div','','card');add(card,'span',needed.has(id)?'Needed evidence':'Other returned information','badge '+(needed.has(id)?'ok':''));add(card,'h3',title(id));add(card,'div',r.top5.includes(id)?'First search selection':'Additional evidence or related record','small');const de=document.createElement('details');card.append(de);add(de,'summary','Show original supplied wording');if(id==='C_ORG')add(de,'p',m.identity.evidence+' This answer explicitly confirmed the organization alias.','original');else for(const sid of recordMap[id]?.sources||[])add(de,'p',sources[sid]?.text||'','original')}
const rb=document.querySelector('#relationships');rb.replaceChildren();if(r.packet){for(const a of r.packet.aliases)add(rb,'p',a.from_name+' and '+a.to_name+' are linked as the same organization, with user confirmation.');for(const h of r.packet.hypotheses)add(rb,'p','Unresolved relationship: '+title(h.source)+' ↔ '+title(h.target)+'. '+h.reason);if(r.packet.confirmations.length)add(rb,'p','Field-level confirmations are supplied with the evidence. A re-mentioned discipline does not refresh the degree or year.')}else add(rb,'p','This method returns ranked memory text. The current graph search can supply replacement labels when explicit change links exist.');window.demoState={question:q.id,system,complete:r.expanded.complete,ids:r.evidence_ids}}
document.querySelector('#question').addEventListener('change',e=>{chosen=Number(e.target.value);options();render()});document.querySelector('#system').addEventListener('change',e=>{system=e.target.value;render()});options();render();window.demo={all,report};
</script></body></html>'''
(OUT/'index.html').write_text(HTML.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')),encoding='utf-8')
(OUT/'results.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
print('Question comparison viewer created: 40 questions, recorded evidence, and plain-language limits.')
